import * as THREE from "three";
import { RubiksCube, simplifyMoves, inverseMove } from "../cube.js";

const cube = new RubiksCube();
function run(moves) {
  for (const m of moves) cube.enqueue(m, "test", 0.01);
  let guard = 0;
  while (cube.busy && guard++ < 100000) cube.update(0.05);
}
const R = { axis: 0, layer: 1, turns: -1 };
const U = { axis: 1, layer: 1, turns: -1 };
const Rp = inverseMove(R), Up = inverseMove(U);

console.log("cubies:", cube.cubies.length, "solved at start:", cube.isSolved());
run([R]);
console.log("solved after R (expect false):", cube.isSolved());
// front-right edge (1,0,1) sticker F should now be on top
const at = (x, y, z) => cube.cubies.find((c) => Math.round(c.position.x) === x && Math.round(c.position.y) === y && Math.round(c.position.z) === z);
const home = (h) => cube.cubies.find((c) => c.userData.home.equals(new THREE.Vector3(...h)));
console.log("front-right edge is now at:", home([1, 0, 1]).position.toArray(), "(expect 1,1,0)");
run([Rp]);
console.log("solved after R R' (expect true):", cube.isSolved());
run([R, R, R, R]);
console.log("solved after R x4:", cube.isSolved());
const sexy = [R, U, Rp, Up];
for (let i = 0; i < 6; i++) run(sexy);
console.log("solved after (R U R' U')x6 (expect true):", cube.isSolved());
for (let i = 0; i < 3; i++) run(sexy);
console.log("solved after 3x (expect false):", cube.isSolved());
cube.reset();
console.log("solved after reset:", cube.isSolved());

// random scramble + reverse
const rnd = [];
for (let i = 0; i < 60; i++) rnd.push({ axis: Math.floor(Math.random() * 3), layer: Math.floor(Math.random() * 3) - 1, turns: [1, -1, 2][Math.floor(Math.random() * 3)] });
run(rnd);
console.log("scrambled solved? (expect false):", cube.isSolved());
const undo = simplifyMoves(rnd).reverse().map(inverseMove);
console.log("simplified length", simplifyMoves(rnd).length, "of", rnd.length);
run(undo);
console.log("solved after reversing (expect true):", cube.isSolved());
// numeric drift check
let maxDrift = 0;
for (const c of cube.cubies) {
  maxDrift = Math.max(maxDrift, c.position.distanceTo(c.userData.home));
  const e = c.quaternion; maxDrift = Math.max(maxDrift, Math.abs(Math.abs(e.w) - 1), Math.abs(e.x), Math.abs(e.y), Math.abs(e.z));
}
console.log("drift/orientation residual:", maxDrift);

// picking
const ray = new THREE.Ray(new THREE.Vector3(0.3, 0.2, 10), new THREE.Vector3(0, 0, -1));
console.log("pick", JSON.stringify(cube.pick(ray)));
const ray2 = new THREE.Ray(new THREE.Vector3(5, 1.2, -0.6), new THREE.Vector3(-1, 0, 0));
console.log("pick", JSON.stringify(cube.pick(ray2)));
console.log("miss", cube.pick(new THREE.Ray(new THREE.Vector3(5, 5, 10), new THREE.Vector3(0, 0, -1))));
EOF
