:root {
  --ink: #e9edfb;
  --ink-dim: #a3adcc;
  --panel: rgba(18, 22, 40, 0.55);
  --panel-border: rgba(255, 255, 255, 0.12);
  --accent: #5b8cff;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--ink);
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  background: radial-gradient(ellipse 90% 80% at 50% 42%, #4a5580 0%, #2a3253 45%, #12152a 100%);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#scene,
#confetti {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

#scene {
  touch-action: none;
  outline: none;
}

#confetti {
  pointer-events: none;
}

.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: max(16px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) 0 max(20px, env(safe-area-inset-left));
  pointer-events: none;
}

.topbar h1 {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 650;
  letter-spacing: 0.02em;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.35);
}

.stats {
  display: flex;
  gap: 10px;
  margin: 0;
}

.stats div {
  min-width: 78px;
  padding: 6px 12px 7px;
  text-align: center;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.stats dt {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--ink-dim);
}

.stats dd {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.toast {
  position: fixed;
  top: 74px;
  left: 50%;
  max-width: calc(100% - 32px);
  padding: 12px 22px;
  text-align: center;
  font-size: 1.05rem;
  font-weight: 600;
  background: rgba(20, 24, 44, 0.78);
  border: 1px solid var(--panel-border);
  border-radius: 999px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
  opacity: 0;
  transform: translate(-50%, -12px);
  transition: opacity 0.3s ease, transform 0.3s ease;
  pointer-events: none;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast small {
  display: block;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--ink-dim);
}

.hint {
  position: fixed;
  left: 50%;
  bottom: calc(96px + env(safe-area-inset-bottom));
  margin: 0;
  width: max-content;
  max-width: calc(100% - 32px);
  text-align: center;
  font-size: 0.85rem;
  color: var(--ink-dim);
  transform: translateX(-50%);
  transition: opacity 0.6s ease;
  pointer-events: none;
}

.hint.hidden {
  opacity: 0;
}

.dock {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px 16px;
  width: max-content;
  max-width: calc(100% - 24px);
  padding: 10px 14px;
  transform: translateX(-50%);
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 18px;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.buttons {
  display: flex;
  gap: 8px;
}

button {
  font: inherit;
  font-size: 0.92rem;
  font-weight: 550;
  color: var(--ink);
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--panel-border);
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, opacity 0.15s ease;
}

button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.16);
}

button:active:not(:disabled) {
  transform: translateY(1px) scale(0.98);
}

button:disabled {
  opacity: 0.4;
  cursor: default;
}

button.primary {
  background: var(--accent);
  border-color: transparent;
  color: #fff;
}

button.primary:hover:not(:disabled) {
  background: #7aa0ff;
}

button.round {
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 50%;
}

button:focus-visible,
input:focus-visible {
  outline: 2px solid #9db9ff;
  outline-offset: 2px;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  color: var(--ink-dim);
}

.speed input {
  width: 96px;
  accent-color: var(--accent);
}

.help {
  position: fixed;
  right: max(16px, env(safe-area-inset-right));
  bottom: calc(92px + env(safe-area-inset-bottom));
  width: min(340px, calc(100% - 32px));
  padding: 14px 18px 16px;
  font-size: 0.86rem;
  line-height: 1.45;
  background: rgba(16, 20, 38, 0.86);
  border: 1px solid var(--panel-border);
  border-radius: 16px;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4);
  -webkit-user-select: text;
  user-select: text;
}

.help[hidden] {
  display: none;
}

.help h2 {
  margin: 0 0 8px;
  font-size: 0.95rem;
}

.help ul {
  margin: 0;
  padding-left: 18px;
}

.help li + li {
  margin-top: 6px;
}

kbd {
  display: inline-block;
  min-width: 1.5em;
  padding: 0 5px;
  font: 600 0.78rem ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  text-align: center;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid var(--panel-border);
  border-radius: 5px;
}

.fallback {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  margin: 0;
  padding: 24px;
  text-align: center;
}

.fallback[hidden] {
  display: none;
}

@media (max-width: 560px) {
  .topbar h1 {
    font-size: 1rem;
  }

  .stats div {
    min-width: 64px;
    padding: 4px 8px 5px;
  }

  .stats dd {
    font-size: 1.05rem;
  }

  .toast {
    top: 66px;
  }

  .hint {
    bottom: calc(132px + env(safe-area-inset-bottom));
  }

  .help {
    bottom: calc(128px + env(safe-area-inset-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast,
  .hint,
  button {
    transition: none;
  }
}

const $ = (id) => document.getElementById(id);

export function formatTime(ms) {
  const total = Math.floor(ms / 1000);
  const s = String(total % 60).padStart(2, "0");
  const m = Math.floor(total / 60) % 60;
  const h = Math.floor(total / 3600);
  return h ? `${h}:${String(m).padStart(2, "0")}:${s}` : `${m}:${s}`;
}

// Thin wrapper around the page's DOM controls.
export class Hud {
  constructor() {
    this.moves = $("moves");
    this.time = $("time");
    this.toastEl = $("toast");
    this.hint = $("hint");
    this.help = $("help");
    this.helpToggle = $("help-toggle");
    this.buttons = {
      scramble: $("scramble"),
      solve: $("solve"),
      undo: $("undo"),
      reset: $("reset"),
    };
    this.speed = $("speed");
    this._toastTimer = 0;

    this.helpToggle.addEventListener("click", () => this.toggleHelp());
  }

  setMoves(n) {
    this.moves.textContent = String(n);
  }

  setTime(ms) {
    const text = formatTime(ms);
    if (this.time.textContent !== text) this.time.textContent = text;
  }

  setEnabled({ scramble, solve, undo }) {
    this.buttons.scramble.disabled = !scramble;
    this.buttons.solve.disabled = !solve;
    this.buttons.undo.disabled = !undo;
  }

  hideHint() {
    this.hint.classList.add("hidden");
  }

  toggleHelp(open = this.help.hidden) {
    this.help.hidden = !open;
    this.helpToggle.setAttribute("aria-expanded", String(open));
  }

  toast(title, detail, duration = 4500) {
    this.toastEl.replaceChildren(title);
    if (detail) {
      const small = document.createElement("small");
      small.textContent = detail;
      this.toastEl.append(small);
    }
    this.toastEl.classList.add("show");
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => this.hideToast(), duration);
  }

  hideToast() {
    clearTimeout(this._toastTimer);
    this.toastEl.classList.remove("show");
  }
}

// A tiny 2D confetti burst drawn on a canvas that sits above the 3D scene.
export class Confetti {
  constructor(canvas, colors) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.colors = colors;
    this.parts = [];
    this.running = false;
    this._last = 0;
    this._frame = this._frame.bind(this);
    this.reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  resize(width, height, dpr) {
    this.canvas.width = Math.round(width * dpr);
    this.canvas.height = Math.round(height * dpr);
    this.dpr = dpr;
    this.width = width;
    this.height = height;
  }

  burst(count = 160) {
    if (this.reducedMotion) return;
    const { width, height } = this;
    for (let i = 0; i < count; i++) {
      const fromLeft = i % 2 === 0;
      const angle = (fromLeft ? -0.35 : -Math.PI + 0.35) + (Math.random() - 0.5) * 0.9;
      const speed = 500 + Math.random() * 700;
      this.parts.push({
        x: fromLeft ? width * 0.12 : width * 0.88,
        y: height * 0.75,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        w: 6 + Math.random() * 7,
        h: 4 + Math.random() * 5,
        rot: Math.random() * Math.PI * 2,
        spin: (Math.random() - 0.5) * 14,
        flip: Math.random() * Math.PI * 2,
        color: this.colors[Math.floor(Math.random() * this.colors.length)],
        life: 2.6 + Math.random() * 1.4,
        age: 0,
      });
    }
    if (!this.running) {
      this.running = true;
      this._last = performance.now();
      requestAnimationFrame(this._frame);
    }
  }

  _frame(now) {
    const dt = Math.min(0.05, (now - this._last) / 1000);
    this._last = now;
    const { ctx, dpr } = this;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, this.width, this.height);

    this.parts = this.parts.filter((p) => p.age < p.life && p.y < this.height + 40);
    for (const p of this.parts) {
      p.age += dt;
      p.vy += 1100 * dt;
      p.vx *= 1 - 1.4 * dt;
      p.vy *= 1 - 0.9 * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
      p.flip += 9 * dt;

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      ctx.scale(1, Math.cos(p.flip));
      ctx.globalAlpha = Math.min(1, (p.life - p.age) * 2);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
      ctx.restore();
    }

    if (this.parts.length) {
      requestAnimationFrame(this._frame);
    } else {
      this.running = false;
      ctx.clearRect(0, 0, this.width, this.height);
    }
  }
}

import { inverseMove, simplifyMoves } from "./cube.js";

const SCRAMBLE_LENGTH = 22;

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

export function randomScramble(length = SCRAMBLE_LENGTH) {
  const moves = [];
  let lastAxis = -1;
  while (moves.length < length) {
    // Never turn the same axis twice in a row, so no move cancels or merges with the last.
    const axis = (lastAxis + 1 + Math.floor(Math.random() * 2) + (lastAxis < 0 ? 1 : 0)) % 3;
    const layer = Math.random() < 0.5 ? -1 : 1;
    const turns = [1, -1, 2][Math.floor(Math.random() * 3)];
    moves.push({ axis, layer, turns });
    lastAxis = axis;
  }
  return moves;
}

// Game rules on top of the cube: move history, undo, scramble / solve, the
// move counter, the timer and detecting when the puzzle has been solved.
export class Game {
  constructor(cube, hud, onSolved) {
    this.cube = cube;
    this.hud = hud;
    this.onSolved = onSolved;

    this.history = []; // every move since the last reset; `user` marks the undoable ones
    this.moves = 0;
    this.sinceSolved = 0; // user moves since the cube was last solved
    this.solved = true;
    this.auto = false; // a scramble or solve is playing; input is locked
    this.challenge = false; // a scramble is in progress and the clock is (or will be) running
    this.timerStart = null;
    this.timerEnd = null;

    cube.onIdle = () => this.settle();
    this.refresh();
  }

  get canInteract() {
    return !this.auto && !this.cube.dragging;
  }

  tick(now) {
    if (this.timerStart !== null) this.hud.setTime((this.timerEnd ?? now) - this.timerStart);
  }

  // A turn made by the player. The keyboard passes `animate` so the cube plays
  // it; a finished drag has already been played by the cube itself.
  userMove(move, animate = true) {
    if (animate) this.cube.enqueue(move, "user");
    if (this.solved) {
      // Starting from a solved cube begins a fresh attempt.
      this.moves = 0;
      this.timerStart = this.timerEnd = null;
      this.hud.setTime(0);
    }
    this.history.push({ axis: move.axis, layer: move.layer, turns: move.turns, user: true });
    this.moves++;
    this.sinceSolved++;
    this.solved = false;
    if (this.challenge && this.timerStart === null) this.timerStart = performance.now();
    this.hud.setMoves(this.moves);
    this.refresh();
  }

  undo() {
    const last = this.history[this.history.length - 1];
    if (!this.canInteract || !last?.user) return;
    this.history.pop();
    this.moves = Math.max(0, this.moves - 1);
    this.sinceSolved = Math.max(0, this.sinceSolved - 1);
    this.cube.enqueue(inverseMove(last), "undo");
    this.hud.setMoves(this.moves);
    this.refresh();
  }

  scramble() {
    if (!this.canInteract) return;
    this.hud.hideToast();
    this.challenge = false;
    this.timerStart = this.timerEnd = null;
    this.moves = 0;
    this.sinceSolved = 0;
    this.hud.setMoves(0);
    this.hud.setTime(0);

    this.auto = true;
    for (const move of randomScramble()) {
      this.history.push({ ...move, user: false });
      this.cube.enqueue(move, "scramble", 0.4);
    }
    this.cube.enqueueCall(() => {
      this.auto = false;
      this.challenge = true; // the clock starts with the first move
      this.solved = false;
      this.refresh();
    });
    this.refresh();
  }

  // Plays the whole history backwards, which always leads back to the solved cube.
  solve() {
    if (!this.canInteract || this.solved) return;
    const sequence = simplifyMoves(this.history).reverse().map(inverseMove);
    this.history = [];
    this.challenge = false;
    this.timerStart = this.timerEnd = null;

    this.auto = true;
    const timeScale = clamp(10 / Math.max(1, sequence.length), 0.35, 1);
    for (const move of sequence) this.cube.enqueue(move, "solve", timeScale);
    this.cube.enqueueCall(() => {
      this.auto = false;
      this.solved = true;
      this.moves = 0;
      this.sinceSolved = 0;
      this.hud.setMoves(0);
      this.hud.setTime(0);
      this.refresh();
    });
    this.refresh();
  }

  reset() {
    this.cube.reset();
    this.history = [];
    this.moves = 0;
    this.sinceSolved = 0;
    this.solved = true;
    this.auto = false;
    this.challenge = false;
    this.timerStart = this.timerEnd = null;
    this.hud.hideToast();
    this.hud.setMoves(0);
    this.hud.setTime(0);
    this.refresh();
  }

  // Called whenever the cube comes to rest.
  settle() {
    if (this.auto) return;
    const solved = this.cube.isSolved();
    if (solved === this.solved) return this.refresh();

    this.solved = solved;
    this.refresh();
    if (!solved) return;

    const earned = this.challenge || this.sinceSolved >= 3;
    this.sinceSolved = 0;
    if (this.timerStart !== null) this.timerEnd = performance.now();
    if (earned) {
      const time = this.timerStart !== null ? this.timerEnd - this.timerStart : null;
      this.onSolved({ moves: this.moves, time });
    }
    this.challenge = false;
  }

  refresh() {
    const last = this.history[this.history.length - 1];
    this.hud.setEnabled({
      scramble: !this.auto,
      solve: !this.auto && !this.solved,
      undo: !this.auto && Boolean(last?.user),
    });
  }
}

