import { chromium } from "playwright-core";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import os from "node:os";

const root = path.resolve(import.meta.dirname, "..");
const dist = path.join(import.meta.dirname, "dist");

export function build() {
  fs.rmSync(dist, { recursive: true, force: true });
  fs.mkdirSync(dist, { recursive: true });
  execFileSync("esbuild", ["main.js", "--bundle", "--format=esm", "--outfile=" + path.join(dist, "main.js"), "--log-level=warning"], { cwd: root, stdio: "inherit" });
  fs.copyFileSync(path.join(root, "index.html"), path.join(dist, "index.html"));
  fs.copyFileSync(path.join(root, "style.css"), path.join(dist, "style.css"));
}

export async function start({ width = 1280, height = 800, touch = false } = {}) {
  build();
  const server = http.createServer((req, res) => {
    const f = path.join(dist, req.url === "/" ? "index.html" : req.url.split("?")[0]);
    if (!fs.existsSync(f)) { res.writeHead(404); res.end(); return; }
    const type = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css" }[path.extname(f)] || "application/octet-stream";
    res.writeHead(200, { "content-type": type });
    fs.createReadStream(f).pipe(res);
  });
  await new Promise((r) => server.listen(0, r));
  const port = server.address().port;
  const browser = await chromium.launch({
    executablePath: path.join(os.homedir(), "Library/Caches/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-mac-arm64/chrome-headless-shell"),
    args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist", "--enable-webgl"],
  });
  const context = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 1, hasTouch: touch });
  const page = await context.newPage();
  const logs = [];
  page.on("console", (m) => logs.push(`[${m.type()}] ${m.text()}`));
  page.on("pageerror", (e) => logs.push(`[pageerror] ${e.message}`));
  await page.goto(`http://localhost:${port}/`);
  return { page, browser, server, logs, close: async () => { await browser.close(); server.close(); } };
}
