import { RubiksCube, inverseMove } from "../cube.js";
import { Game } from "../game.js";

const log = [];
const hud = {
  setMoves: (n) => (hud.moves = n), setTime: (t) => (hud.time = t), setEnabled: (e) => (hud.enabled = e),
  hideToast() {}, hideHint() {}, toast() {},
};
const cube = new RubiksCube();
cube.speed = 3;
let solvedEvents = [];
const game = new Game(cube, hud, (r) => solvedEvents.push(r));
const spin = () => { let g = 0; while (cube.busy && g++ < 100000) cube.update(0.05); cube.update(0.05); };
const assert = (c, m) => { if (!c) { console.error("FAIL:", m); process.exitCode = 1; } else console.log("ok:", m); };

game.scramble();
assert(game.auto && !hud.enabled.scramble, "scramble locks controls");
spin();
assert(!game.auto && game.challenge && !game.solved && !cube.isSolved(), "scramble finishes, challenge armed");
assert(!hud.enabled.undo && hud.enabled.solve, "undo disabled until user moves; solve enabled");

game.userMove({ axis: 0, layer: 1, turns: -1 });
spin();
game.userMove({ axis: 1, layer: 1, turns: 1 });
spin();
assert(hud.moves === 2 && game.timerStart !== null, "two user moves counted, timer started");
game.undo(); spin();
assert(hud.moves === 1, "undo decrements");
game.undo(); spin();
assert(hud.moves === 0 && !hud.enabled.undo, "undo back to scramble boundary; can't undo scramble");
game.undo(); spin();
assert(hud.moves === 0, "extra undo is a no-op");

// user moves then solve
for (let i = 0; i < 7; i++) game.userMove({ axis: i % 3, layer: (i % 2) * 2 - 1, turns: [1, -1, 2][i % 3] });
spin();
game.solve();
assert(game.auto, "solve locks controls");
spin();
assert(cube.isSolved() && game.solved && !game.auto, "solve returns to solved");
assert(solvedEvents.length === 0, "auto-solve doesn't celebrate");

// manual solve celebrates: R U R' U' U R U' R'
const R = { axis: 0, layer: 1, turns: -1 }, U = { axis: 1, layer: 1, turns: -1 };
for (const m of [R, U, inverseMove(R), inverseMove(U), U, R, inverseMove(U), inverseMove(R)]) game.userMove(m);
spin();
assert(cube.isSolved() && solvedEvents.length === 1 && solvedEvents[0].moves === 8, "manual solve celebrates with 8 moves: " + JSON.stringify(solvedEvents));

// trivial R R' does not celebrate
game.userMove(R); game.userMove(inverseMove(R)); spin();
assert(solvedEvents.length === 1, "R R' does not celebrate");

// undo returning to solved does not celebrate
game.userMove(R); game.userMove(U); game.userMove(R); game.userMove(U); spin();
assert(!cube.isSolved(), "4 moves unsolve it");
for (let i = 0; i < 4; i++) { game.undo(); }
spin();
assert(cube.isSolved() && solvedEvents.length === 1, "undoing back to solved does not celebrate");

// reset mid scramble
game.scramble(); cube.update(0.1); game.reset();
assert(cube.isSolved() && !game.auto && !cube.busy, "reset mid-scramble is clean");
spin();
assert(cube.isSolved(), "still solved after settling");
